// TestActionNames asserts every announced goast action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Callable,
		provider.Calls,
		provider.CheckLineWidth,
		provider.Composites,
		provider.ConstGroups,
		provider.Deps,
		provider.Format,
		provider.Funcs,
		provider.LoadSourceFile,
		provider.Methods,
		provider.Metrics,
		provider.RawString,
		provider.Render,
		provider.ReturnString,
		provider.ReturnStrings,
		provider.SortDeclarations,
		provider.Structs,
		provider.TypeDoc,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

